GN['ja.es'] = {
A1: [
 {t:'X は Y です: «X es Y»',
  b:`<p>La oración básica es <b>tema + [[は]] + información + [[です]]</b>: [[私 は 学生 です 。]] = Soy estudiante. La partícula は se escribe con el kana «ha», pero se lee <b>wa</b>.</p><p>Negación: [[じゃ ありません]] — [[先生 じゃ ありません 。]] = No soy profesor. Pregunta: se añade [[か]] al final — [[学生 です か 。]]</p><p class="tip">El japonés omite «yo / tú» cuando se entiende, como el español. El verbo y です van siempre al final.</p>`,
  ex:['Soy estudiante.','Esto es un libro.','El señor Tanaka no es profesor.','¿Eres estudiante?'],
  q:['«Soy médico»:','«¿Qué es esto?»:']},
 {t:'Las partículas を, に, で, へ',
  b:`<p>Las partículas van <b>después</b> de la palabra e indican su función:</p><div class="tblwrap"><table><tr><th>partícula</th><th>función</th><th>ejemplo</th></tr><tr><td>[[を]] (o)</td><td>objeto directo</td><td>[[水 を 飲みます]]</td></tr><tr><td>[[へ]] (e) / [[に]]</td><td>dirección «a»</td><td>[[学校 へ 行きます]]</td></tr><tr><td>[[に]]</td><td>hora, lugar donde está algo</td><td>[[七時 に 起きます]]</td></tr><tr><td>[[で]]</td><td>lugar de la acción, medio</td><td>[[図書館 で 読みます]]</td></tr></table></div><p class="tip">Como partículas, を se lee «o» y へ se lee «e».</p>`,
  ex:['Bebo agua.','Voy a la escuela.','Leo libros en la biblioteca.','Me levanto a las siete.'],
  q:['«Como pan»:','«Juego en el parque»:']},
 {t:'Verbos corteses: -ます, -ません, -ました',
  b:`<p>La forma cortés del verbo termina en [[ます]] y sirve para presente y futuro: [[飲みます]] = bebo / beberé.</p><div class="tblwrap"><table><tr><th></th><th>afirmativo</th><th>negativo</th></tr><tr><td>presente / futuro</td><td>[[飲みます]]</td><td>[[飲みません]]</td></tr><tr><td>pasado</td><td>[[飲みました]]</td><td>[[飲みません でした]]</td></tr></table></div><p class="tip">El verbo no cambia según la persona: «yo bebo / tú bebes / ella bebe» son todos [[飲みます]].</p>`,
  ex:['Tomo café todas las mañanas.','No como carne.','Ayer vi una película.','El domingo no trabajé.'],
  q:['«Ayer vi la tele»:','«No bebo alcohol»:']},
 {t:'Dos tipos de adjetivos: い y な',
  b:`<p>Los <b>adjetivos-い</b> terminan en い y van directamente delante del sustantivo: [[大きい 家]] (una casa grande). Negativo: い → [[く ない]]: [[寒く ない です]] (no hace frío).</p><p>Los <b>adjetivos-な</b> necesitan [[な]] delante del sustantivo: [[静か な 町]] (una ciudad tranquila); al final de la frase solo です: [[きれい です]].</p><p class="tip">きれい termina en い, pero es un adjetivo-な: apréndelo como excepción.</p>`,
  ex:['Este libro es interesante.','Hoy no hace frío.','Es una ciudad tranquila.','El parque es bonito.'],
  q:['«una casa grande»:','«una habitación tranquila»:']}
],
A2: [
 {t:'La forma て: peticiones y «estar + -ndo»',
  b:`<p>La forma て une verbos y es la base de muchas estructuras: [[待ちます]] → [[待って]], [[開けます]] → [[開けて]], [[します]] → [[して]].</p><p>Petición: forma て + [[ください]] = haga, por favor: [[窓 を 開けて ください 。]]</p><p>Acción en curso o estado: forma て + [[います]]: [[雨 が 降って います 。]] = Está lloviendo.</p>`,
  ex:['Abra la ventana, por favor.','Ahora está lloviendo.','Mi hermano trabaja en un banco.'],
  q:['«Espere un momento, por favor»:','«Mamá está cocinando»:']},
 {t:'«Hay»: あります y います',
  b:`<p>[[あります]] se usa para cosas y plantas, [[います]] para personas y animales. El lugar lleva [[に]] y la cosa [[が]]: [[机 の 上 に 本 が あります 。]] = Hay un libro sobre la mesa.</p><p class="tip">Palabras de lugar: [[上]] encima, [[中]] dentro, [[下]] debajo, [[前]] delante, [[隣]] al lado — con の: [[机 の 上]].</p>`,
  ex:['Hay un libro sobre la mesa.','Hay niños en el parque.','¿Dónde está la estación?'],
  q:['«Hay un gato»:','«Hay un bolígrafo sobre la mesa»:']},
 {t:'Querer: -たい y ほしい',
  b:`<p>«Quiero hacer» = raíz de ます + [[たい]]: [[行きます]] → [[行きたい です]]. Se comporta como un adjetivo-い: [[行きたく ない]] = no quiero ir.</p><p>«Quiero una cosa» = cosa + [[が ほしい です]]: [[新しい 車 が ほしい です 。]]</p>`,
  ex:['Quiero ir a Japón.','Quiero beber agua.','Quiero un coche nuevo.'],
  q:['«Quiero comer sushi»:','«Quiero un móvil nuevo»:']},
 {t:'Comparación: より y 一番',
  b:`<p>A は B [[より]] adjetivo = A es más … que B: [[東京 は 大阪 より 大きい です 。]]</p><p>Para elegir entre dos: [[〜 の ほう が]]: [[地下鉄 の ほう が 速い です 。]] El más: [[一番]]: [[一番 高い 山]] = la montaña más alta.</p><p class="tip">El adjetivo no cambia al comparar; todo el trabajo lo hacen las partículas.</p>`,
  ex:['Tokio es más grande que Osaka.','El metro es más rápido.','El Fuji es la montaña más alta de Japón.'],
  q:['«Mi hermano es más alto que yo»:','«mi color favorito»:']}
],
B1: [
 {t:'La forma simple y ～と思います',
  b:`<p>Cada forma cortés tiene una forma simple (de diccionario) que se usa con amigos y dentro de frases largas: [[来ます]] → [[来る]], [[来ません]] → [[来ない]], [[です]] → [[だ]].</p><p>«Creo que …» = forma simple + [[と 思います]]: [[明日 は 雨 だ と 思います 。]]</p><p class="tip">Con sustantivos y adjetivos-な se pone だ antes de と: [[学生 だ と 思います]].</p>`,
  ex:['Creo que mañana lloverá.','Creo que no vendrá.','Creo que este libro es interesante.'],
  q:['«Creo que vendrá»:','«Creo que mañana hará sol»:']},
 {t:'Experiencia: ～た こと が あります',
  b:`<p>Pasado simple (forma た) + [[こと が あります]] = «he … alguna vez»: [[富士山 に 登った こと が あります 。]] = He subido al Fuji.</p><p>Nunca: [[〜た こと が ありません]]; [[一度 も]] = ni una vez.</p><p class="tip">La forma た es la forma て cambiando て/で por た/だ: [[行って]] → [[行った]], [[飲んで]] → [[飲んだ]].</p>`,
  ex:['He subido al monte Fuji.','¿Has comido sushi alguna vez?','Nunca he estado en Japón.'],
  q:['«He estado en Kioto»:','«No lo he visto ni una vez»:']},
 {t:'Condicionales: ～たら y ～ば',
  b:`<p>[[〜たら]] (forma た + ら) = si / cuando: [[時間 が あったら 、 電話 します 。]] = Si tengo tiempo, te llamo.</p><p>[[〜ば]] = si (condición general): verbos [[行けば]], adjetivos-い い → [[ければ]]: [[安ければ 買います 。]]</p><p class="tip">〜たら es lo más común en la conversación y también significa «cuando / en cuanto»: [[駅 に 着いたら]] = cuando llegues a la estación.</p>`,
  ex:['Si tengo tiempo, te llamo.','Si es barato, lo compro.','Si llueve, me quedo en casa.'],
  q:['«Llámame cuando llegues a la estación»:','«Si es barato, lo compro»:']}
],
B2: [
 {t:'La voz pasiva: ～られる',
  b:`<p>La pasiva añade [[〜れる / 〜られる]] a la raíz del verbo: [[建てる]] → [[建てられる]], [[盗む]] → [[盗まれる]], [[する]] → [[される]]. Quien hace la acción lleva [[に]]: [[先生 に ほめられました 。]] = El profesor me elogió.</p><p class="tip">El japonés también usa la pasiva para cosas desagradables que te pasan: [[財布 を 盗まれました 。]] = Me robaron la cartera.</p>`,
  ex:['Ese puente se construyó hace cien años.','El profesor me elogió.','Este libro está traducido a muchos idiomas.'],
  q:['«Me robaron la cartera»:','«En Japón se habla japonés»:']},
 {t:'Dar y recibir: あげる, くれる, もらう',
  b:`<p>[[あげる]] = dar (de mí / de mi lado a otros). [[くれる]] = dar (a mí / a mi lado). [[もらう]] = recibir: [[先生 に 辞書 を もらいました 。]]</p><p>Con la forma て expresan favores: [[手伝って くれました]] (me ayudó), [[手伝って もらいました]] (conseguí que me ayudaran).</p>`,
  ex:['Le di un libro a mi amigo.','Mi madre me regaló un reloj.','Recibí un diccionario de mi profesor.'],
  q:['«Mi hermana me regaló flores»:','«Mi amigo me ayudó (recibí su ayuda)»:']},
 {t:'Describir sustantivos con frases enteras',
  b:`<p>El japonés no tiene «que / quien» relativo. Una frase en forma simple va <b>delante</b> del sustantivo: [[昨日 会った 人]] = la persona que conocí ayer; [[私 が 読んで いる 本]] = el libro que estoy leyendo.</p><p class="tip">Dentro de esa frase, el sujeto suele llevar が, no は.</p>`,
  ex:['El libro que estoy leyendo es interesante.','La persona que conocí ayer es profesora.','Esta es la ciudad donde nací.'],
  q:['«el pastel que hizo mi madre»:','«una persona que habla japonés»:']}
],
C1: [
 {t:'Keigo: lenguaje honorífico y humilde',
  b:`<p>El <b>honorífico</b> (sonkeigo) eleva a la otra persona: [[お 〜 に なる]] — [[お帰り に なりました]]; verbos especiales: [[いらっしゃる]] (estar / venir / ir), [[おっしゃる]] (decir), [[召し上がる]] (comer).</p><p>El <b>humilde</b> (kenjōgo) te rebaja a ti: [[申します]] (decir, me llamo), [[伺います]] (visitar, preguntar), [[参ります]] (ir, venir).</p><p class="tip">Nunca uses verbos honoríficos para hablar de ti mismo.</p>`,
  ex:['El profesor ya se ha ido a casa.','El presidente está en la sala de reuniones.','Me llamo Tanaka.'],
  q:['«¿Cómo se llama usted?» (honorífico):','«Mañana iré a verle» (humilde):']},
 {t:'El causativo: ～させる',
  b:`<p>[[〜せる / 〜させる]] = hacer / dejar que alguien haga: [[食べる]] → [[食べさせる]], [[行く]] → [[行かせる]]. La persona que actúa lleva [[に]] (o を con verbos intransitivos).</p><p>[[〜させて ください]] = déjeme …: [[少し 考えさせて ください 。]]</p>`,
  ex:['La madre hizo que el niño comiera verdura.','Mi jefe me mandó de viaje de negocios.','Déjeme pensarlo un poco.'],
  q:['«El profesor hizo escribir una redacción a los alumnos»:','«Déjeme pensarlo»:']}
],
C2: [
 {t:'El estilo escrito: である',
  b:`<p>Los artículos, ensayos y textos académicos usan [[で ある]] en lugar de です / だ: [[言語 は 文化 の 鏡 で ある 。]] = La lengua es el espejo de la cultura.</p><p>Giros escritos típicos: [[〜 と 言えよう]] (puede decirse), [[〜 の で ある]] (es que…, énfasis), [[〜 に ほかならない]] (no es otra cosa que).</p>`,
  ex:['La lengua es el espejo de la cultura.','Esto puede llamarse un problema grave.','Empezando por la conclusión, el plan tuvo éxito.'],
  q:['«Japón es un país insular» (escrito):','«El problema se resolvió» (escrito enfático):']},
 {t:'Refranes (ことわざ)',
  b:`<p>Los refranes japoneses son breves y gráficos: [[猿 も 木 から 落ちる 。]] (hasta los monos se caen de los árboles = al mejor cazador se le va la liebre), [[石 の 上 に も 三年 。]] (tres años incluso sobre una piedra = con paciencia se gana el cielo), [[花 より 団子 。]] (dango antes que flores = lo práctico antes que lo bonito).</p><p class="tip">Aprende cada refrán entero, junto con su imagen.</p>`,
  ex:['Hasta los monos se caen de los árboles.','Tres años incluso sobre una piedra.','Dango antes que flores.'],
  q:['«Hasta los monos se caen de los árboles»:','«Dango antes que flores»:']}
]};
